const TP4 = [
{id:"hipaa-1",topic:"hipaa",lvl:1,title:"PHI or not?",hours:"2 hours",
 company:"MedBill India, a Noida medical billing firm working for US clinics.",
 data:{"Scenarios":[["#","Scenario"],["1","A US clinic's patient list with names, dates of birth and diagnoses, sent to MedBill for billing"],["2","The same list with all 18 HIPAA identifiers removed under Safe Harbor"],["3","A fitness app (not working for any health plan or provider) storing users' heart rates"],["4","MedBill employees' own sick-leave records"],["5","A claim file with a patient's email and treatment code"],["6","A research dataset with ZIP codes reduced to the first 3 digits (where population > 20,000), no other identifiers"],["7","A voicemail from a patient to the clinic about test results, transcribed by MedBill"],["8","Aggregated count: '1,240 claims processed in March'"]]},
 problem:"New staff don't know which data triggers HIPAA safeguards.",
 objective:"Decide for each scenario whether it's PHI, de-identified, or outside HIPAA, and who the covered entity / business associate is.",
 deliverables:["Table: scenario → PHI? → why → entity roles"],
 steps:[["Ask who holds it","Covered entity or its business associate?"],["Ask if it's health info linked to identifiers","If yes → PHI."],["Check de-identification","Safe Harbor removes 18 identifiers."],["Employment records","Employer HR records aren't PHI even if health-related."]],
 rubric:[["1, 5 and 7 = PHI (MedBill as business associate)",1],["2 and 6 = de-identified under Safe Harbor",1],["3 = outside HIPAA (not a covered entity or BA)",1],["4 = employment record, not PHI",1],["8 = not PHI (aggregated)",0]],
 hints:["HIPAA covers who holds the data, not just what it is.","Employer-held employee health records are excluded from PHI.","Three-digit ZIP is allowed under Safe Harbor when the area has over 20,000 people."],
 key:{approach:"Who holds it → identifiable health info? → de-identified? → exclusions.",
  sample:"1 PHI; clinic = covered entity, MedBill = BA. 2 De-identified (not PHI). 3 Not HIPAA (consumer app not acting for a CE) — other laws may apply. 4 Not PHI (employment record). 5 PHI. 6 De-identified if all other identifiers removed and 3-digit ZIP rule met. 7 PHI. 8 Not PHI.",
  tips:["'Health data' and 'PHI' aren't the same thing.","De-identified data still deserves care in contracts."]},
 videos:[["Why: what PHI is","HIPAA 18 identifiers PHI explained"],["How: covered entity vs business associate","HIPAA covered entity vs business associate explained"]]},

{id:"hipaa-2",topic:"hipaa",lvl:2,title:"Review a Business Associate Agreement",hours:"4 hours",
 company:"MedBill India receives a BAA from a new US clinic.",
 data:{"Draft BAA clauses":[["#","Clause"],["1","BA may use PHI to perform billing services for Covered Entity."],["2","BA will use appropriate safeguards."],["3","BA will report incidents it considers significant."],["4","BA may disclose PHI to its affiliates for any business purpose."],["5","Agreement silent on subcontractors."],["6","Agreement silent on what happens to PHI at termination."],["7","BA will make PHI available for patient access requests within 30 days of the CE's request."]]},
 problem:"Your manager wants a checklist-based review before signing.",
 objective:"Check the draft against the BAA elements HIPAA requires and list what's missing or wrong.",
 deliverables:["Checklist: required element → present? → issue → fix","Top 3 issues for negotiation"],
 steps:[["List required elements","Permitted uses/disclosures; safeguards incl. Security Rule compliance; reporting of breaches and security incidents; subcontractor flow-down; access/amendment/accounting support; HHS access to books and records; return/destruction at termination; termination for breach."],["Compare","Mark present, weak or missing."],["Write fixes","Specific language."],["Prioritise","Biggest legal gaps first."]],
 rubric:[["Flags 'significant incidents' as too narrow (must report breaches of unsecured PHI and security incidents)",1],["Flags clause 4 (affiliates for any purpose) as impermissible",1],["Flags missing subcontractor flow-down and termination return/destruction",1],["Notes Security Rule compliance should be explicit",1],["Mentions HHS access to books and records",0]],
 hints:["A BA can only use PHI as the BAA permits — 'any business purpose' fails.","Subcontractors who touch PHI must agree to the same restrictions.","What happens to PHI when the contract ends?"],
 key:{approach:"Required elements checklist → gaps → fixes → priorities.",
  sample:"Issues: (3) reporting limited to 'significant' incidents → must report any breach of unsecured PHI and security incidents, with a timeline; (4) disclosures to affiliates for any purpose → delete; limit to permitted uses; (5) missing subcontractor flow-down → add; (6) missing return/destruction at termination → add; (2) 'appropriate safeguards' → 'comply with the Security Rule'; add HHS access to books and records; termination right for material breach.",
  tips:["Indian BAs often accept clinic templates; read them anyway.","Breach reporting timelines are a common negotiation point."]},
 videos:[["Why: business associate agreements","business associate agreement BAA explained HIPAA"],["How: BAA required provisions","BAA required provisions checklist"]]},

{id:"hipaa-3",topic:"hipaa",lvl:3,title:"Security Rule risk analysis for a billing BPO",hours:"8–10 hours",
 company:"MedBill India: 150 billers on Windows desktops, a US clinic portal accessed via browser, files exchanged by SFTP, shared office with another company.",
 problem:"A client asks for MedBill's HIPAA risk analysis, and a laptop was lost last month.",
 objective:"Do a Security Rule-structured risk analysis (administrative, physical, technical), assess the lost-laptop incident under the Breach Notification Rule, and recommend fixes.",
 deliverables:["Safeguard gap table (admin/physical/technical)","Risk ratings for top 8 gaps","Lost-laptop assessment: breach? who notifies whom, by when?","Remediation plan"],
 steps:[["Inventory where ePHI lives","Portals, SFTP, desktops, email, paper."],["Walk each safeguard family","Risk analysis, training, access control, audit logs, encryption, facility access, device disposal."],["Rate gaps","Likelihood × impact."],["Assess the laptop","Encrypted? What data? Low probability of compromise?"],["Plan fixes","Prioritised with owners."]],
 rubric:[["Covers all three safeguard families",1],["Identifies shared office and device controls as physical risks",1],["Lost-laptop analysis: if unencrypted with PHI, BA notifies the covered entity; CE notifies individuals within 60 days of discovery",1],["Encryption recommended (makes PHI 'secured')",1],["Prioritised remediation",0]],
 hints:["Encrypted PHI meeting HHS guidance is 'secured', which changes breach duties.","BAs notify the covered entity; the CE notifies patients.","Shared offices need visitor and screen controls."],
 key:{approach:"Inventory → three families → ratings → breach assessment → plan.",
  sample:"Top gaps: no formal risk analysis (admin); no USB/print controls (technical); shared office without visitor logs (physical); generic shared logins on the clinic portal (technical — unique user IDs required); no audit log review; laptops not all encrypted.\nLost laptop: if unencrypted and held PHI, presume a breach unless a documented risk assessment shows low probability of compromise; MedBill must notify the clinic without unreasonable delay (and per the BAA timeline); the clinic notifies patients within 60 days of discovery, HHS, and media if 500+ residents of a state.\nPlan: encrypt all devices (2 weeks), unique portal IDs (1 month), USB blocking (1 month), formal risk analysis annually.",
  tips:["Unique user IDs are an explicit technical safeguard.","Encryption is the single biggest breach-impact reducer."]},
 videos:[["Why: HIPAA risk analysis","HIPAA security risk analysis explained"],["How: breach notification rule","HIPAA breach notification rule 60 days 500"]]},

{id:"glba-1",topic:"glba",lvl:1,title:"Check a bank privacy notice",hours:"2 hours",
 company:"A US credit union's privacy notice (Indian back-office team asked to review).",
 data:{"Notice excerpt":[["Section","Text"],["What we collect","Your information"],["Why","To run our business"],["Sharing","We share information with companies we choose"],["Opt-out","Write to our head office"],["Contact","None listed"]]},
 problem:"The compliance lead suspects the notice doesn't meet GLBA's Privacy Rule.",
 objective:"Compare the notice with GLBA Privacy Rule expectations and list gaps.",
 deliverables:["Gap list with what's required","A rewritten version of the sharing and opt-out sections"],
 steps:[["Recall what notices must explain","Categories of NPI collected and disclosed, categories of affiliates and non-affiliated third parties, opt-out rights and methods, how information is protected."],["Compare section by section","Is it specific?"],["Rewrite","Clear categories and easy opt-out (toll-free number, online form)."]],
 rubric:[["Flags vague categories of information collected",1],["Flags vague sharing (must describe categories of recipients)",1],["Flags hard opt-out method",1],["Rewrite gives specific categories and easy opt-out methods",1]],
 hints:["The model form uses a table: 'Reasons we can share your personal information'.","Opt-out should be reasonable: phone, online, or mail-in form.","Contact details for questions are expected."],
 key:{approach:"Required elements → gaps → rewrite.",
  sample:"Gaps: 'your information' — list categories (SSN, income, account balances, transaction history); 'companies we choose' — describe affiliates and non-affiliates and reasons; opt-out by letter only — offer phone and online; no contact. Rewrite (sharing): 'We share your name and account history with our affiliates for their everyday business. We do not share with non-affiliates to market to you unless you allow it.' Opt-out: 'Call 1-800-… or visit …/privacy.'",
  tips:["Regulators publish a model privacy form; use it as a benchmark.","Specific beats long."]},
 videos:[["Why: GLBA privacy rule","GLBA financial privacy rule privacy notice opt out"],["How: model privacy notice","GLBA model privacy form explained"]]},

{id:"glba-2",topic:"glba",lvl:2,title:"Safeguards Rule programme check",hours:"5 hours",
 company:"A US mortgage broker (non-bank, under FTC) with its operations team in Pune.",
 data:{"Current state":[["Element","Status"],["Qualified individual","Part-time IT contractor, no written mandate"],["Written risk assessment","None"],["MFA","Only on email"],["Encryption","Laptops yes; database no"],["Training","Once at onboarding"],["Vendor oversight","None"],["Incident response plan","None"],["Board reporting","None"],["Breach notice to FTC","Unaware of the requirement"]]},
 problem:"A partner bank asks for proof of Safeguards Rule compliance.",
 objective:"Assess the broker against the FTC Safeguards Rule and write a 90-day plan.",
 deliverables:["Gap table: requirement → status → gap → action → owner → day","Note on the FTC notification requirement for breaches affecting 500+ consumers"],
 steps:[["List requirements","Qualified individual, written risk assessment, safeguards (access, encryption, MFA), training, vendor oversight, IR plan, annual report to the board, testing/monitoring, FTC notice for 500+ consumer incidents."],["Compare","Use the current state."],["Plan","90 days, ordered by risk."]],
 rubric:[["Covers qualified individual, risk assessment, MFA, encryption, vendor oversight, IR plan, board reporting",1],["Identifies FTC notice for incidents affecting 500+ consumers (within 30 days of discovery)",1],["Plan is prioritised and owned",1],["Database encryption and MFA beyond email",1]],
 hints:["MFA is required for anyone accessing customer information systems.","The qualified individual needs a clear mandate and to report to the board.","The FTC notification rule took effect in 2024."],
 key:{approach:"Requirement list → gaps → prioritised plan.",
  sample:"Days 1–15: appoint qualified individual in writing; start written risk assessment; extend MFA to all systems with customer information. Days 15–45: encrypt the database; IR plan including FTC notice (within 30 days of discovery for incidents involving 500+ consumers); vendor inventory and contract review. Days 45–90: training programme; annual written report to the board; vulnerability scanning/testing schedule.",
  tips:["Written evidence is half the battle.","The 500-consumer notice is easy to miss."]},
 videos:[["Why: FTC Safeguards Rule","FTC GLBA safeguards rule requirements explained"],["How: FTC breach notification amendment","FTC safeguards rule notification requirement 500 consumers"]]},

{id:"glba-3",topic:"glba",lvl:3,title:"FCRA permissible purpose audit",hours:"6–8 hours",
 company:"A lending BPO in Gurugram pulling US credit reports for a US lender client.",
 data:{"Credit pulls (sample of 12)":[["#","Agent","Reason logged","Linked application?"],["1","A01","New loan application","Yes"],["2","A02","Account review of existing borrower","Yes (existing account)"],["3","A03","'Checking a friend's score'","No"],["4","A01","Pre-screened offer list","Yes (prescreen programme)"],["5","A04","(blank)","No"],["6","A02","New loan application","Yes"],["7","A05","Collections on existing account","Yes"],["8","A03","'Training practice'","No"],["9","A06","New loan application","Yes"],["10","A04","Employment screening of a BPO job applicant","No (no written authorisation on file)"],["11","A05","New loan application","Application withdrawn before pull"],["12","A06","Account review","Yes"]]},
 problem:"The US client's audit is next month. Your Provana experience makes you the natural reviewer.",
 objective:"Test each pull for a permissible purpose, write findings, and design controls.",
 deliverables:["Testing table: pull → permissible? → reason","Findings with five Cs","Control design (preventive and detective)"],
 steps:[["Recall permissible purposes","Credit transaction initiated by the consumer, account review, collection on an account, written authorisation for employment, firm offer (prescreen) under program rules."],["Test each pull","Reason + link to a legitimate case."],["Spot patterns","Same agents? Blank reasons?"],["Write findings","Five Cs."],["Design controls","System requires a linked application/account and reason code; monthly review of pulls without links; training; disciplinary process."]],
 rubric:[["Flags 3 and 8 (personal and 'training') as no permissible purpose",1],["Flags 5 (blank reason, no link)",1],["Flags 10 (employment screening without written authorisation)",1],["Flags 11 (pull after withdrawal) as questionable",1],["Preventive system control plus detective review",0]],
 hints:["Curiosity and training are never permissible purposes.","Employment use requires written authorisation from the person.","If the application was withdrawn, is there still a purpose?"],
 key:{approach:"Purpose test → patterns → findings → controls.",
  sample:"Exceptions: 3 (A03 personal), 8 (A03 training), 5 (A04 blank), 10 (A04 employment without authorisation), 11 (A05 after withdrawal). 5 of 12 (42%) exceptions; agents A03 and A04 account for 4.\nFinding: credit pulls are possible without a linked application/account or reason code. Consequence: FCRA violations, client contract breach, consumer harm. Actions: system block — pulls require a linked case ID and reason code; weekly exception report; retrain all agents; investigate A03 and A04.",
  tips:["Patterns by person suggest misconduct, not just process weakness.","Preventive system controls beat after-the-fact reviews."]},
 videos:[["Why: FCRA permissible purpose","FCRA permissible purpose explained"],["How: compliance testing","compliance testing sample approach explained"]]},

{id:"secfinra-1",topic:"secfinra",lvl:1,title:"Which rule, which clock?",hours:"2 hours",
 company:"A New York-licensed wealth firm (registered investment adviser and broker-dealer), listed on the NYSE, with operations in Pune.",
 data:{"Incidents":[["#","Incident"],["1","A vendor that hosts client statements discovers a breach"],["2","Clients' SSNs and account numbers were accessed by an attacker"],["3","A ransomware attack is judged material to the listed parent company"],["4","A cybersecurity event reportable to NYDFS occurs"],["5","An employee texts clients about trades on personal WhatsApp"],["6","A suspicious change of a client's bank account details is detected"]]},
 problem:"The team needs a quick reference for which rule applies and what the deadline is.",
 objective:"Match each incident to the rule and deadline or action.",
 deliverables:["Table: incident → rule → deadline/action → who acts"],
 steps:[["Recall the clocks","Reg S-P: service providers notify within 72 hours; affected individuals within 30 days. NYDFS: 72 hours. SEC 8-K Item 1.05: 4 business days after materiality determination."],["Recall FINRA/SEC recordkeeping","Off-channel communications must be captured."],["Recall Reg S-ID","Red flags programme."]],
 rubric:[["1: vendor notifies firm within 72 hours (Reg S-P)",1],["2: notify affected individuals within 30 days (Reg S-P)",1],["3: 8-K within 4 business days of materiality decision",1],["4: NYDFS within 72 hours",1],["5: recordkeeping violation (off-channel); 6: Reg S-ID red flag",0]],
 hints:["There are two 72-hour clocks — different rules.","The 8-K clock starts at the materiality determination, not discovery.","WhatsApp trade chats aren't captured by the firm's archive."],
 key:{approach:"Rule → clock → owner.",
  sample:"1 Reg S-P service provider → notify the firm ASAP, ≤72h. 2 Reg S-P → individuals within 30 days. 3 SEC 8-K Item 1.05 → within 4 business days after determining materiality (Legal/CFO). 4 NYDFS Part 500 → 72 hours (CISO). 5 SEC Rule 17a-4 / FINRA 4511 → off-channel communications breach; preserve, report internally, discipline. 6 Reg S-ID → red flag; verify via known contact, block change.",
  tips:["Build one incident playbook that routes all of these.","Clocks run in parallel."]},
 videos:[["Why: SEC Reg S-P amendments","SEC Regulation S-P amendments 2024 explained incident response 30 days"],["How: SEC cyber disclosure 8-K","SEC cybersecurity disclosure rule 8-K item 1.05 four business days explained"]]},

{id:"secfinra-2",topic:"secfinra",lvl:2,title:"Write a Reg S-P incident response programme",hours:"5–6 hours",
 company:"A US investment adviser with $900M AUM (a 'smaller entity'), using an Indian outsourcing partner for client onboarding.",
 problem:"The adviser had to comply with amended Reg S-P by 3 June 2026 and has nothing written.",
 objective:"Write the incident response programme outline, service-provider oversight requirements and a customer notice template.",
 deliverables:["Programme outline: detect, assess, contain, notify, recover, document","Service-provider requirements (72-hour notice, oversight)","Customer notice template with required content","Recordkeeping list"],
 steps:[["Define scope","Customer information and sensitive customer information."],["Write the programme steps","Who assesses, how sensitive data exposure is determined."],["Service providers","Contract terms: notify within 72 hours; due diligence and monitoring."],["Notice","Within 30 days: what happened, what data, what the firm is doing, what customers can do, contact."],["Records","What to keep and for how long."]],
 rubric:[["Programme covers detection through recovery with roles",1],["Service providers must notify within 72 hours; oversight described",1],["Customer notice within 30 days with required content",1],["Notes the smaller-entity compliance date (3 June 2026)",0],["Recordkeeping covered",0]],
 hints:["The Indian partner is a service provider; its contract must reflect the 72-hour duty.","Notice can be avoided only if the firm determines sensitive information wasn't and isn't reasonably likely to be used in a harmful way — document that.","Keep records of the assessment either way."],
 key:{approach:"Scope → programme → vendors → notice → records.",
  sample:"Programme: Detect (monitoring, staff and vendor reports) → Assess (CCO + IT within 24h: what data, sensitive?) → Contain → Notify (affected individuals within 30 days unless documented determination of no reasonable likelihood of substantial harm or inconvenience) → Recover → Document. Vendor: due diligence, contract clause for ≤72h breach notice, annual review. Notice template: description of incident, types of data, date range, steps taken, contact number, advice (credit freeze, fraud alerts).",
  tips:["Exceptions to notice need written reasoning.","Vendor contracts must catch up with the rule."]},
 videos:[["Why: Reg S-P incident response","Regulation S-P incident response program requirements"],["How: customer breach notice","data breach notification letter example"]]},

{id:"secfinra-3",topic:"secfinra",lvl:3,title:"Off-channel communications control plan",hours:"8 hours",
 company:"A broker-dealer's India operations (300 staff) after a peer firm was fined for WhatsApp trading chats.",
 problem:"The CCO wants a plan that would hold up to an SEC/FINRA exam.",
 objective:"Design policy, technology, monitoring, attestation and discipline controls for business communications, with metrics.",
 deliverables:["Policy summary (approved channels, prohibited channels, what counts as business communication)","Technology plan (capture tools, device management)","Monitoring and surveillance approach","Attestation and training plan","Discipline framework","Metrics"],
 steps:[["Define business communications","Anything about the firm's business, incl. trades and client advice."],["Approved channels","Captured email, archived chat apps, recorded lines."],["Technology","Managed devices, archiving for approved apps."],["Monitor","Lexicon surveillance, sampling, red flags (e.g. 'let's take this to WhatsApp')."],["Attest and train","Quarterly attestations; training with examples."],["Discipline","Proportionate, consistent, documented."],["Metrics","Attestation completion, exceptions found, time to remediate."]],
 rubric:[["Clear definition of business communications and approved channels",1],["Capture/archiving technology for approved channels (17a-4 retention)",1],["Surveillance with red-flag lexicon and sampling",1],["Attestations, training and discipline",1],["Metrics for oversight",0]],
 hints:["Banning WhatsApp isn't enough; how will you detect it?","Retention must meet SEC Rule 17a-4.","Supervisors must supervise (FINRA 3110)."],
 key:{approach:"Define → approve → capture → monitor → attest → discipline → measure.",
  sample:"Policy: business communications only on firm email, archived Teams, recorded lines; personal messaging apps prohibited for business. Technology: managed phones with archived messaging; capture vendor for approved chat. Surveillance: lexicon ('WhatsApp me', 'personal number'), 5% weekly sample review by supervisors, alerts. Attestation: quarterly by every registered person. Discipline: matrix from warning to termination. Metrics: 100% attestation; surveillance alerts reviewed in 5 days; exceptions trend.",
  tips:["Detection is the heart of the plan.","Senior staff must follow it visibly."]},
 videos:[["Why: off-channel communications fines","SEC off-channel communications fines WhatsApp recordkeeping explained"],["How: communications surveillance","communications surveillance compliance broker dealer"]]},

{id:"indiafin-1",topic:"indiafin",lvl:1,title:"Which Indian regulator?",hours:"2 hours",
 company:"A group with an NBFC, a payments app and a stockbroker in India.",
 data:{"Scenarios":[["#","Scenario"],["1","Ransomware on the broker's trading servers"],["2","Payment app stores UPI transaction data in a Singapore data centre"],["3","NBFC loan app collects users' contact lists"],["4","Personal data of 50,000 app users leaked"],["5","Broker's cyber audit due under SEBI's framework"],["6","NBFC board wants an IT strategy committee"]]},
 problem:"The group compliance team needs to route each matter correctly.",
 objective:"Identify the regulator(s) and rule for each scenario.",
 deliverables:["Table: scenario → regulator(s) → rule → action"],
 steps:[["Recall the layers","DPDP (Board) for personal data; CERT-In for cyber incidents; RBI for banks/NBFCs/payments; SEBI for market intermediaries."],["Map each scenario","Some involve more than one."]],
 rubric:[["1: CERT-In (6h) + SEBI (CSCRF/incident reporting)",1],["2: RBI payment data localisation",1],["3: RBI digital lending rules + DPDP consent/necessity",1],["4: DPDP Board + affected users (and CERT-In if a listed incident)",1],["5 SEBI CSCRF; 6 RBI IT Governance Master Direction",0]],
 hints:["Many incidents trigger CERT-In AND a sector regulator.","Payment data storage is an RBI rule.","Loan apps have their own RBI digital lending directions."],
 key:{approach:"Layer by layer.",
  sample:"1 CERT-In within 6 hours; SEBI incident reporting under CSCRF. 2 RBI 2018 payment data storage directive — move data to India. 3 RBI digital lending directions (no access to contacts beyond need) + DPDP consent/necessity. 4 DPDP — intimate Board and affected users; CERT-In if listed incident. 5 SEBI CSCRF audit. 6 RBI Master Direction on IT Governance.",
  tips:["Draw a routing table once and reuse it.","Several clocks run at once."]},
 videos:[["Why: Indian financial cyber rules","RBI SEBI cybersecurity regulations India explained"],["How: CERT-In reporting","CERT-In directions 2022 6 hours 180 days logs explained"]]},

{id:"indiafin-2",topic:"indiafin",lvl:2,title:"Payment data localisation check",hours:"4–5 hours",
 company:"PaySetu's architecture.",
 data:{"Data flows":[["#","Flow"],["1","UPI transaction records stored in AWS Mumbai region"],["2","Nightly copy of transaction data to an analytics warehouse in AWS Singapore"],["3","Fraud-scoring vendor in the US receives full transaction details in real time and stores them for 90 days"],["4","Customer support tool (US SaaS) receives transaction IDs and amounts in tickets"],["5","Backups of the transaction database stored in AWS Mumbai and AWS Frankfurt"],["6","Card network settlement messages processed abroad and returned within one business day"]]},
 problem:"RBI's payment data storage directive requires payment system data to be stored only in India.",
 objective:"Identify which flows break the directive, which may be acceptable, and write a remediation plan.",
 deliverables:["Table: flow → compliant? → reason → fix","Remediation plan with priorities"],
 steps:[["Understand the rule","Store the entire payment data only in India; processing abroad is allowed if data is deleted abroad and brought back within a short window (RBI FAQs mention one business day or 24 hours)."],["Assess each flow","Storage vs processing; retention abroad."],["Plan fixes","Move, mask, minimise or delete."]],
 rubric:[["Flags 2 (Singapore warehouse) and 5 (Frankfurt backups) as storage outside India",1],["Flags 3 (US vendor storing 90 days)",1],["Treats 6 as within the processing-abroad allowance",1],["Considers 4 and suggests minimisation/masking",1],["Prioritised plan",0]],
 hints:["Backups count as storage.","Processing abroad is tolerated only if the data comes back and is deleted there quickly.","Can the vendor work with masked or tokenised data?"],
 key:{approach:"Storage vs processing → retention abroad → fix.",
  sample:"Non-compliant: 2 Singapore warehouse (move to Mumbai); 3 US fraud vendor storing 90 days (contract to delete within 24 hours or use India-hosted instance/tokenised data); 5 Frankfurt backups (move to a second Indian region). Acceptable: 1; 6 (returned within one business day, per RBI FAQs). Review: 4 — minimise ticket data (mask amounts/IDs) or use India data residency.",
  tips:["Backups are the most common miss.","Vendors often offer an India region — ask."]},
 videos:[["Why: RBI payment data localisation","RBI payment data localisation 2018 explained"],["How: data residency in cloud","data residency cloud India region explained"]]},

{id:"indiafin-3",topic:"indiafin",lvl:3,title:"Integrated incident reporting playbook (India)",hours:"8–10 hours",
 company:"The same group (NBFC + payments + broker).",
 problem:"Every incident becomes a scramble over who reports to whom. The board wants one playbook.",
 objective:"Build a single playbook routing incidents to CERT-In, the Data Protection Board, RBI and SEBI with clocks, RACI and templates.",
 deliverables:["Decision flowchart (what kind of incident → which notifications)","Clock table (regulator → trigger → deadline → owner)","RACI","Two templates (CERT-In report fields; DPDP intimation to users)","Exercise plan to test it"],
 steps:[["List triggers","Cyber incident types; personal data breach; payment system disruption; market intermediary incident."],["Set clocks","CERT-In 6 hours; DPDP: without delay + detailed report in 72 hours; RBI and SEBI timelines as per their rules (verify the current circulars)."],["Assign RACI","CISO, DPO, Compliance, Legal, CEO, Comms."],["Draft templates","Fields only."],["Plan an exercise","Tabletop twice a year."]],
 rubric:[["Flowchart routes by incident type and entity",1],["Clock table includes CERT-In 6h and DPDP 72h detailed report",1],["Notes that RBI/SEBI timelines must be confirmed from current circulars",1],["RACI with single accountability",1],["Templates and testing plan",0]],
 hints:["Clocks start when the incident is noticed.","Write 'verify current circular' where you're unsure — reviewers reward honesty.","Who has authority to send the CERT-In report at 3am?"],
 key:{approach:"Triggers → routing → clocks → RACI → templates → testing.",
  sample:"Clock table: CERT-In — listed cyber incident — 6h from noticing — CISO. DPDP Board — personal data breach — intimation without delay; detailed report within 72h — DPO. Affected Data Principals — without delay — DPO + Comms. RBI — incidents at NBFC/payment entities — per RBI reporting directions (confirm current timelines) — Compliance Head. SEBI — broker incidents — per CSCRF/SEBI circulars (confirm) — Broker Compliance Officer.\nRACI: incident declaration A: CISO; regulator notifications A: CEO, R: CISO/DPO/Compliance.\nTesting: semi-annual tabletop using a ransomware-with-exfiltration scenario.",
  tips:["One owner per notification avoids gaps.","Pre-approved templates save hours."]},
 videos:[["Why: integrated incident reporting","incident reporting India RBI SEBI CERT-In DPDP compared"],["How: incident playbook","incident response playbook template explained"]]},

{id:"c-ir-1",topic:"c-ir",lvl:1,title:"Event, incident or breach?",hours:"2 hours",
 company:"LedgerLeaf's security team queue.",
 data:{"Items":[["#","What was observed"],["1","One failed login for a user who mistyped"],["2","300 failed logins in 5 minutes on an admin account from abroad"],["3","Antivirus quarantined a malicious attachment before anyone opened it"],["4","An employee emailed a customer's bank statement to the wrong customer"],["5","The website was down for 2 hours due to a cloud outage"],["6","An attacker logged in and downloaded 2,000 customer records"],["7","A laptop with encrypted disk was lost"],["8","A misconfigured storage bucket was public for 3 days; access logs show no downloads"]]},
 problem:"Analysts over- and under-escalate.",
 objective:"Classify each as event, incident or personal data breach, set a severity, and say who's notified.",
 deliverables:["Table: item → class → severity → reasoning → notify"],
 steps:[["Event","Anything observable."],["Incident","Threatens confidentiality, integrity or availability."],["Breach","Personal data actually or likely compromised."],["Severity","Based on impact."]],
 rubric:[["1 = event; 2 = incident",1],["4 and 6 = personal data breaches",1],["7 = incident, likely not a notifiable breach due to encryption",1],["8 = incident needing investigation; logs suggest no access but document",1],["Severity and notification reasoning",0]],
 hints:["A wrong recipient is a breach even without hacking.","Availability incidents can be incidents without being breaches.","Logs showing no access lower the risk but still need documenting."],
 key:{approach:"Event → incident → breach test → severity.",
  sample:"1 Event. 2 Incident (high) — block, check for success. 3 Event/incident (low) — control worked. 4 Breach (medium) — DPDP intimation assessment, contact recipient. 5 Incident (availability), not a breach. 6 Breach (critical) — CERT-In, DPDP, clients. 7 Incident (low) — encrypted, document. 8 Incident (medium) — breach risk assessed; logs show no downloads; document decision.",
  tips:["Document why you decided NOT to notify.","Severity drives speed."]},
 videos:[["Why: event vs incident vs breach","event vs incident vs breach explained"],["How: incident severity","incident severity levels explained"]]},

{id:"c-ir-2",topic:"c-ir",lvl:2,title:"Write a post-incident report",hours:"4–5 hours",
 company:"Kavach IT.",
 data:{"Timeline":[["Time","Event"],["Mon 09:05","Finance clerk receives email 'Updated vendor bank details' from look-alike domain"],["Mon 09:40","Clerk updates vendor bank account in ERP; no second approval required"],["Tue 11:00","₹18 lakh paid to the new account"],["Fri 15:00","Real vendor chases unpaid invoice"],["Fri 15:30","Finance realises fraud; security informed"],["Fri 16:30","Bank contacted; ₹6 lakh frozen"],["Mon 10:00","Email logs show the attacker had read the CFO's mailbox for 3 weeks (no MFA)"]]},
 problem:"Leadership wants a report: what happened, why, and what changes.",
 objective:"Write a post-incident report with root causes, impact, what went well/badly and corrective actions.",
 deliverables:["Executive summary (5 lines)","Timeline","Root cause analysis (5 whys)","Impact","Actions with owners and dates"],
 steps:[["Summarise","What, when, impact, status."],["Analyse root causes","Ask 'why' repeatedly: payment changed without verification → no control requiring callback → …"],["Separate trigger from root cause","Phishing triggered it; missing controls let it succeed."],["Assess impact","Money, data (CFO mailbox read), reputation."],["Write actions","Preventive and detective, with owners."]],
 rubric:[["Identifies root causes: no bank-change verification, no dual approval, no MFA on CFO mailbox",1],["Recognises the CFO mailbox compromise as a data breach to assess",1],["Actions include callback verification, dual approval and MFA",1],["Clear executive summary",0],["Lessons on detection delay (4 days)",0]],
 hints:["Why did it take until Friday to notice?","The attacker knew the invoice details — how?","Which single control would have stopped the payment?"],
 key:{approach:"Summary → timeline → 5 whys → impact → actions.",
  sample:"Summary: A business email compromise led to ₹18 lakh paid to a fraudster; ₹6 lakh recovered. The attacker had access to the CFO's mailbox for 3 weeks because it lacked MFA.\nRoot causes: no MFA on executive mailboxes; bank detail changes accepted by email without callback; no dual approval for bank changes; no alerting on look-alike domains.\nImpact: ₹12 lakh loss; CFO mailbox contents (likely personal and vendor data) exposed — assess DPDP breach duties.\nActions: MFA for all (1 week); callback on known number for any bank change (immediate); dual approval in ERP (2 weeks); look-alike domain monitoring (1 month).",
  tips:["Blameless reports produce better facts.","Look for how the attacker knew so much."]},
 videos:[["Why: post-incident reviews","post incident review blameless explained"],["How: root cause analysis 5 whys","5 whys root cause analysis example"]]},

{id:"c-cloud-1",topic:"c-cloud",lvl:1,title:"Who secures what?",hours:"2 hours",
 company:"LedgerLeaf uses AWS EC2 (IaaS), AWS RDS (managed database, PaaS-like) and Google Workspace (SaaS).",
 data:{"Responsibilities":[["#","Item"],["1","Physical data centre security"],["2","Patching the EC2 operating system"],["3","Patching the RDS database engine"],["4","Who can access the RDS database"],["5","Google Workspace user MFA settings"],["6","Gmail server hardware"],["7","Encryption setting on S3 buckets"],["8","Security group (firewall) rules for EC2"],["9","Data uploaded to Google Drive and who it's shared with"],["10","Hypervisor security"]]},
 problem:"Engineers assume 'AWS handles security'.",
 objective:"Assign each item to provider, customer or shared, with a one-line reason.",
 deliverables:["Table: item → provider/customer/shared → reason"],
 steps:[["Recall the model","Provider: of the cloud. Customer: in the cloud."],["Adjust by service type","More managed = more provider responsibility for the platform."],["Remember the constant","Data, identities and access are always the customer's."]],
 rubric:[["Physical, hypervisor, Gmail hardware = provider",1],["EC2 OS patching = customer; RDS engine patching = provider (managed)",1],["Access, MFA, encryption settings, security groups, sharing = customer",1],["Reasons given",0]],
 hints:["IaaS: you manage the operating system.","Managed databases patch the engine for you, but not who can log in.","Settings you can change in a console are yours."],
 key:{approach:"Of the cloud vs in the cloud, adjusted by service type.",
  sample:"Provider: 1, 3, 6, 10. Customer: 2, 4, 5, 7, 8, 9.",
  tips:["Data and access are always yours.","Most cloud breaches are customer misconfigurations."]},
 videos:[["Why: shared responsibility","cloud shared responsibility model explained"],["How: IaaS PaaS SaaS","IaaS PaaS SaaS explained simply"]]},

{id:"c-cloud-2",topic:"c-cloud",lvl:2,title:"Review a cloud configuration export",hours:"4–5 hours",
 company:"LedgerLeaf's AWS account.",
 data:{"Findings from a configuration export":[["#","Setting"],["1","Root account: MFA disabled; access keys exist"],["2","S3 bucket 'kyc-scans': public read ON; encryption ON"],["3","S3 bucket 'website-assets': public read ON (static website)"],["4","CloudTrail logging: OFF in two regions"],["5","Security group 'prod-db': port 5432 open to 0.0.0.0/0"],["6","IAM user 'intern1': AdministratorAccess policy"],["7","Default encryption on new EBS volumes: OFF"],["8","Password policy: minimum 8 characters, no MFA requirement for console users"]]},
 problem:"Before a client audit, the CTO wants a prioritised fix list.",
 objective:"Rate each setting, decide whether it's a real issue, and prioritise fixes.",
 deliverables:["Table: setting → issue? → severity → fix → effort","Top 5 fixes in order"],
 steps:[["Understand each setting","What could go wrong?"],["Spot intentional exceptions","A public website bucket may be fine."],["Rate severity","Data exposure and account takeover first."],["Write fixes","Specific console actions."]],
 rubric:[["Root MFA off + root access keys = critical",1],["kyc-scans public = critical; website-assets public = acceptable (by design)",1],["Database open to internet = critical; intern with admin = high",1],["CloudTrail off flagged (detection gap)",1],["Prioritised top 5",0]],
 hints:["Not every public bucket is a mistake.","Root access keys should usually not exist at all.","Logging off means you can't investigate later."],
 key:{approach:"Understand → exceptions → severity → fix.",
  sample:"Critical: 1 enable root MFA, delete root keys; 2 block public access on kyc-scans; 5 restrict 5432 to app servers. High: 6 remove admin from intern1, least privilege; 4 enable CloudTrail in all regions with log integrity. Medium: 7 default EBS encryption; 8 stronger password policy + MFA for console users. OK: 3 (static website), but confirm no sensitive files.",
  tips:["Context decides severity.","Turn on logging before you need it."]},
 videos:[["Why: cloud misconfigurations","cloud misconfiguration explained data breach"],["How: AWS security best practices","AWS security best practices for beginners"]]},

{id:"c-cloud-3",topic:"c-cloud",lvl:3,title:"Write a cloud security baseline",hours:"8 hours",
 company:"Kavach IT is moving client workloads to AWS and Azure.",
 problem:"Each team configures accounts differently. Clients ask for 'your cloud security standard'.",
 objective:"Write a baseline standard of 12–15 testable controls for cloud accounts, mapped to CIS Benchmarks and ISO 27001, with how each is checked.",
 deliverables:["Baseline document with numbered controls","Mapping table (CIS area, ISO Annex A)","Evidence/automated check per control","Exception process"],
 steps:[["Cover the areas","Identity (root/MFA/least privilege), logging, encryption, network, storage, monitoring, backup, tagging/ownership, region/data residency."],["Write testable controls","E.g. 'CloudTrail enabled in all regions with log file validation.'"],["Map and check","How to verify (config rules, CSPM tool, manual review)."],["Exceptions","Approval, expiry."]],
 rubric:[["12+ testable controls across identity, logging, encryption, network, storage",1],["Each control has a verification method",1],["Includes data residency (India) considerations",1],["Mapping to CIS/ISO",0],["Exception process with expiry",0]],
 hints:["Write controls so an automated tool could check them.","Data residency matters for Indian financial clients.","Every resource needs an owner tag."],
 key:{approach:"Areas → testable controls → mapping → checks → exceptions.",
  sample:"CB-01 Root/global admin accounts have MFA and no access keys (CIS 1.x; ISO A.8.5). Check: config rule. CB-04 Logging enabled in all regions, retained 1 year, tamper-evident (ISO A.8.15). CB-07 Storage blocks public access unless an approved exception (ISO A.8.3). CB-09 Databases not reachable from the internet (ISO A.8.20). CB-11 Encryption at rest by default with managed keys (ISO A.8.24). CB-13 Workloads for Indian regulated clients deployed only in India regions (ISO A.5.31 legal requirements).",
  tips:["Testable + automated = sustainable.","Exceptions must expire."]},
 videos:[["Why: cloud security baselines","cloud security baseline explained"],["How: CIS benchmarks for cloud","CIS AWS foundations benchmark explained"]]},

{id:"aigov-1",topic:"aigov",lvl:1,title:"Classify eight AI systems",hours:"2 hours",
 company:"Various uses at Kavach IT and its clients (EU market).",
 data:{"Systems":[["#","System"],["1","Social scoring of citizens by a public body"],["2","AI that ranks job applicants"],["3","Customer-service chatbot"],["4","AI spam filter"],["5","AI credit-scoring for loan decisions"],["6","AI-generated marketing images"],["7","Real-time emotion recognition of employees at work"],["8","AI that suggests code to developers"]]},
 problem:"The legal team wants a quick sort.",
 objective:"Classify each under the EU AI Act (prohibited, high-risk, limited/transparency, minimal) with reasons.",
 deliverables:["Table: system → tier → reason → main obligation"],
 steps:[["Recall prohibited practices","Social scoring; emotion recognition at work/school (with exceptions)."],["Recall Annex III high-risk","Employment, creditworthiness, education, etc."],["Recall transparency","Chatbots, generated content."]],
 rubric:[["1 and 7 = prohibited",1],["2 and 5 = high-risk",1],["3 and 6 = transparency obligations",1],["4 and 8 = minimal",1]],
 hints:["Emotion recognition in the workplace is on the prohibited list (with narrow exceptions).","Hiring and credit decisions are in Annex III.","People should know when they talk to AI."],
 key:{approach:"Prohibited → high-risk → transparency → minimal.",
  sample:"1 Prohibited. 2 High-risk (employment). 3 Limited — disclose AI interaction. 4 Minimal. 5 High-risk (creditworthiness). 6 Limited — label AI-generated content. 7 Prohibited (emotion recognition at work). 8 Minimal.",
  tips:["Check prohibitions first.","Timelines differ by tier."]},
 videos:[["Why: EU AI Act tiers","EU AI Act risk categories explained"],["How: prohibited AI practices","EU AI Act prohibited practices explained"]]},

{id:"aigov-2",topic:"aigov",lvl:2,title:"Write a generative AI acceptable-use policy",hours:"4–5 hours",
 company:"Kavach IT staff use ChatGPT-style tools for code, emails and client documents.",
 problem:"A developer pasted client source code into a public AI tool. Leadership wants rules, not a ban.",
 objective:"Write a 2-page generative AI acceptable-use policy with approved tools, data rules, review duties and training.",
 deliverables:["Policy (purpose, scope, approved tools, data you may/may not enter, human review, IP and confidentiality, disclosure, incidents, exceptions)","One-page quick guide for staff","Rollout plan"],
 steps:[["Decide approved tools","Enterprise versions with no training on your data."],["Set data rules","No client confidential, personal or secret data in unapproved tools."],["Human review","Outputs reviewed before use; no automated decisions about people."],["Disclosure and IP","When to tell clients; licence checks for code."],["Incidents","How to report a mistaken paste."]],
 rubric:[["Clear approved vs prohibited tools",1],["Data rules for client, personal and confidential data",1],["Human review and accountability for outputs",1],["Incident reporting for data entered by mistake",1],["Quick guide and rollout",0]],
 hints:["Banning tools drives use underground; approve safe ones.","Personal data in prompts is processing under DPDP/GDPR.","Who is accountable for an AI-written email? The sender."],
 key:{approach:"Tools → data → review → disclosure → incidents → rollout.",
  sample:"Approved: company enterprise AI assistant (no training on inputs, data residency agreed). Prohibited: entering client confidential information, personal data, credentials or source code into any other AI tool. Review: you are responsible for any AI-assisted output; check facts, code licences and bias. No AI-only decisions about employees or candidates. Disclose AI use to clients where contracts require. Mistaken paste: report to security within 1 hour.",
  tips:["Give people a safe tool, then rules.","Keep the quick guide to one page."]},
 videos:[["Why: generative AI policies","generative AI acceptable use policy explained"],["How: AI governance in companies","AI governance framework for companies"]]},

{id:"t-onetrust-1",topic:"t-onetrust",lvl:1,title:"Design a compliant cookie banner",hours:"2–3 hours",
 company:"ShopKart's website, visited from India, the EU and California.",
 problem:"The current banner says 'By continuing you accept all cookies'.",
 objective:"Design the banner and preference centre text and behaviour that would satisfy GDPR/ePrivacy, DPDP and CCPA, as you'd configure in a consent tool like OneTrust.",
 deliverables:["Banner text and buttons","Preference centre categories with descriptions","Behaviour rules per region (opt-in vs opt-out, GPC)","Consent record fields"],
 steps:[["Categorise cookies","Strictly necessary, functional, analytics, advertising."],["Write banner text","Short, clear, equal 'Accept all' and 'Reject all'."],["Set regional behaviour","EU: opt-in, nothing non-essential before consent. California: 'Do Not Sell or Share' and honour GPC. India: notice + consent for non-essential processing."],["Record consent","Timestamp, version, choices, region."]],
 rubric:[["'Reject all' as easy as 'Accept all' for EU",1],["Non-essential cookies blocked before consent in EU",1],["GPC honoured and 'Do Not Sell or Share' for California",1],["Consent records defined",1],["Clear category descriptions",0]],
 hints:["'By continuing' is not consent under GDPR.","Regional rules can be configured as geolocation rules in consent tools.","Record the banner version shown."],
 key:{approach:"Categories → text → regional rules → records.",
  sample:"Banner: 'We use cookies to run our site and, with your permission, to understand usage and show relevant ads. [Accept all] [Reject all] [Manage choices]'. Categories: Necessary (always on); Functional; Analytics; Advertising. EU: opt-in, tags blocked until consent. California: banner plus 'Your Privacy Choices' link; GPC signal treated as opt-out of sale/sharing. India: notice with purpose, consent for non-essential, withdrawal link in footer. Records: consent ID, timestamp, region, banner version, choices.",
  tips:["Equal prominence is checked by regulators.","Test that tags really don't fire before consent."]},
 videos:[["Why: cookie consent rules","cookie consent banner compliance explained"],["How: OneTrust cookie setup","OneTrust cookie consent tutorial"]]},

{id:"t-onetrust-2",topic:"t-onetrust",lvl:2,title:"Build a privacy impact assessment template",hours:"5 hours",
 company:"ShopKart's privacy team wants a PIA template like those in OneTrust's assessment module.",
 problem:"Business teams fill in free-text forms that miss key risks.",
 objective:"Design a 15–20 question PIA with answer types, branching logic and automatic risk flags.",
 deliverables:["Question list with answer types (yes/no, multi-select, text)","Branching rules (e.g. if 'children' → extra questions)","Risk flag rules (e.g. 'sensitive data + new technology' → DPIA required)","Approval workflow (submitter → privacy → DPO)"],
 steps:[["Cover the essentials","Purpose, data types, data subjects, volume, sources, legal basis, sharing, transfers, retention, security, new tech, automated decisions, children."],["Pick answer types","Structured answers enable automation."],["Add branching","Show follow-ups only when needed."],["Add risk flags","Rules that escalate to a full DPIA."],["Define workflow","Who reviews and approves."]],
 rubric:[["Covers purpose, data, subjects, legal basis, sharing, transfers, retention, security",1],["Uses structured answer types",1],["Branching for children, sensitive data or transfers",1],["Risk flags that trigger a DPIA",1],["Approval workflow",0]],
 hints:["Free text is hard to score; use options where possible.","Which answers should automatically raise the risk level?","Who signs off at the end?"],
 key:{approach:"Coverage → structure → branching → flags → workflow.",
  sample:"Q4 Which data categories? [multi: contact, financial, health, location, biometric, children's, government ID] → if health/biometric/children → flag 'Sensitive' and show Q4a–c. Q9 Will data leave India/EU? [yes/no] → if yes → transfer questions. Flag rule: Sensitive AND (new technology OR large scale OR profiling) → 'DPIA required'. Workflow: submitter → privacy analyst review (5 days) → DPO approval for flagged items.",
  tips:["Good templates make good decisions repeatable.","Keep it short enough that teams finish it."]},
 videos:[["Why: privacy impact assessments","privacy impact assessment explained"],["How: OneTrust assessments","OneTrust privacy impact assessment DPIA tutorial"]]},

{id:"t-onetrust-3",topic:"t-onetrust",lvl:3,title:"Design a privacy programme workflow in a tool",hours:"8–10 hours",
 company:"PaySetu buys a privacy management platform (like OneTrust) to prepare for DPDP.",
 problem:"The tool is bought; nobody has designed how the programme will run in it.",
 objective:"Design the workflows for data inventory, assessments, DSARs, vendor risk and breach management, with stages, owners, SLAs and dashboard metrics, mapped to DPDP duties.",
 deliverables:["Workflow diagrams for 5 processes","Stage/owner/SLA table","Dashboard design (8 metrics)","DPDP mapping (which workflow evidences which duty)","90-day implementation plan"],
 steps:[["Start from duties","DPDP Sec 5–14 obligations."],["Design each workflow","Trigger → stages → owners → SLA → closure evidence."],["Connect workflows","New vendor → inventory update → PIA if personal data."],["Define dashboards","Overdue DSARs, open high-risk PIAs, vendors due review, breach timelines."],["Plan rollout","Pilot with one business unit."]],
 rubric:[["Five workflows with stages, owners and SLAs",1],["Workflows connected (vendor → inventory → assessment)",1],["Mapped to DPDP duties",1],["Meaningful dashboard metrics",1],["Realistic rollout plan",0]],
 hints:["Tools only work if every workflow has an owner and an SLA.","Breach workflow needs the 72-hour detailed report clock.","Pilot before rolling out to everyone."],
 key:{approach:"Duties → workflows → connections → dashboards → rollout.",
  sample:"DSAR: request in portal → identity verification (2 days) → system search tasks to owners (5 days) → privacy review → response (deadline tracked) → closure with evidence. Breach: report → triage (1h) → CERT-In decision (≤6h) → DPDP intimation → detailed report (72h) → lessons. Vendor: intake → tiering → questionnaire → DPA → inventory update → annual review. Metrics: DSARs on time %, open high-risk PIAs, Tier 1 vendors overdue, average breach triage time, inventory coverage %, consent withdrawal processing time.",
  tips:["Design processes first, then configure the tool.","Every workflow ends in evidence."]},
 videos:[["Why: privacy program management","privacy program management CIPM explained"],["How: OneTrust platform overview","OneTrust platform overview demo"]]},

{id:"t-servicenow-1",topic:"t-servicenow",lvl:1,title:"Get a PDI and tour the platform",hours:"2–3 hours",
 company:"You, preparing for ServiceNow GRC roles.",
 problem:"Recruiters ask 'Have you used ServiceNow?' You need honest hands-on experience.",
 objective:"Get a free Personal Developer Instance, navigate lists and forms, build a filter and a simple report, and document what you did.",
 deliverables:["Notes with screenshots: login, a list view, a filtered list, a form, a saved report","What each screen is used for in GRC work"],
 steps:[["Sign up","developer.servicenow.com → request an instance."],["Explore lists","Open any list (e.g. Incidents); add columns; sort."],["Filter","Build a condition (e.g. priority = 1 and state ≠ closed) and save it."],["Open a form","See fields, related lists, activity history."],["Report","Create a bar chart report from a list."],["Write notes","How this maps to GRC: lists of controls, filters for overdue issues, reports for dashboards."]],
 rubric:[["Evidence of a working instance (screenshots described)",1],["Filtered list with a saved condition",1],["A report created",1],["GRC relevance explained",0]],
 hints:["PDIs sleep when unused; wake them from the developer portal.","Filters use condition builder breadcrumbs — click them to edit.","Reports: right-click a column header → Bar Chart."],
 key:{approach:"Instance → lists → filter → form → report → notes.",
  sample:"Notes example: 'Filtered Incident list: Priority = 1 AND Active = true. In GRC, the same approach finds Controls where Status = Non-compliant. Report: bar chart of incidents by category; in GRC this becomes issues by entity for the monthly dashboard.'",
  tips:["Keep your PDI active by logging in regularly.","Honest phrasing for resumes: 'ServiceNow (personal developer instance practice)'."]},
 videos:[["Why: ServiceNow basics","what is ServiceNow explained beginners"],["How: lists, filters and reports","ServiceNow lists forms filters basics"]]},

{id:"t-servicenow-2",topic:"t-servicenow",lvl:2,title:"Model five ISO controls in the IRM data model",hours:"5 hours",
 company:"Kavach IT wants ISO 27001 tracked in ServiceNow IRM.",
 problem:"Implementers need a business analyst who can translate the standard into IRM records.",
 objective:"Map five ISO 27001 controls into the IRM structure: authority document → citations → policy → control objectives → controls (per entity) → risk statements, in your PDI if IRM is available, otherwise in a spreadsheet that mirrors the tables.",
 deliverables:["Spreadsheet or PDI records for 5 controls across 2 entities (e.g. India delivery, Germany office)","Short explanation of each record type"],
 steps:[["Choose 5 controls","A.5.15 access control, A.8.5 secure authentication, A.8.13 backup, A.5.24 incident planning, A.6.3 awareness."],["Authority document and citations","ISO 27001:2022; one citation per control."],["Policy and control objectives","Which policy statement implements each."],["Controls per entity","Each objective becomes a control for each entity with an owner."],["Risk statements","What could go wrong if the control fails."]],
 rubric:[["Correct hierarchy from authority document to controls",1],["Controls generated per entity with owners",1],["Risk statements linked",1],["Clear explanation of record types",0]],
 hints:["One control objective becomes several controls — one per entity.","Citations are the specific clauses/controls of the standard.","Owners are people in each entity."],
 key:{approach:"Standard → citations → policy → objectives → per-entity controls → risks.",
  sample:"Authority doc: ISO/IEC 27001:2022. Citation: A.8.13 Information backup. Policy statement: 'Critical data is backed up daily and restores are tested quarterly.' Control objective: Backup and restore testing. Controls: CO-BKP-IN (India delivery, owner: IT Ops Lead IN), CO-BKP-DE (Germany, owner: IT Lead DE). Risk statement: Loss of client data due to failed or untested backups.",
  tips:["Entities make the model scale.","This is exactly what IRM BA interviews test."]},
 videos:[["Why: ServiceNow IRM data model","ServiceNow IRM policy and compliance data model authority document citation control"],["How: GRC playlist","ServiceNow GRC IRM tutorial beginners"]]},

{id:"t-servicenow-3",topic:"t-servicenow",lvl:3,title:"Design an attestation and issue workflow",hours:"8 hours",
 company:"Kavach IT's compliance team runs quarterly control attestations in ServiceNow IRM.",
 problem:"Owners ignore attestations, and failed controls never become tracked issues.",
 objective:"Design (and build what you can in a PDI) an attestation campaign and issue management process with SLAs, escalations and a dashboard.",
 deliverables:["Attestation design: questions, evidence required, schedule, reminders","Issue workflow: creation rules, severity, owner, SLA, remediation, verification, closure","Escalation rules","Dashboard design with 6 indicators"],
 steps:[["Design attestation questions","'Did this control operate this quarter? Attach evidence.'"],["Define triggers","'No' or missing evidence → issue created automatically."],["Set SLAs","High 30 days, medium 60, low 90."],["Escalations","Reminder at 7 days, manager at 14, compliance head at 30."],["Dashboard","Attestation completion, non-compliant controls by entity, issues overdue, average remediation time."]],
 rubric:[["Attestation requires evidence, not just 'yes'",1],["Automatic issue creation for failed/missing attestations",1],["SLAs and escalations by severity",1],["Verification step before closing issues",1],["Dashboard indicators",0]],
 hints:["A 'yes' with no evidence shouldn't count.","Who verifies a fix before an issue closes?","Escalations work best when they reach managers automatically."],
 key:{approach:"Attestation → issue trigger → SLA → escalation → verification → dashboard.",
  sample:"Attestation: quarterly; 3 questions per control (operated? evidence attached? any exceptions?). No/missing evidence → auto-create issue (severity from control criticality). SLAs: High 30d, Medium 60d, Low 90d. Escalation: day 7 reminder; day 14 manager; day 30 compliance head; overdue highs reported to the risk committee. Closure requires compliance verification of evidence. Dashboard: attestation completion %, non-compliant controls by entity, open issues by severity, overdue issues, mean time to remediate, repeat issues.",
  tips:["Verification before closure stops 'paper fixes'.","Repeat issues reveal weak controls."]},
 videos:[["Why: control attestation","control attestation process GRC explained"],["How: ServiceNow GRC demo","ServiceNow GRC demo create policy control risk issue"]]}
];
/* Extra metadata for the 11 original projects so they slot into the ladders. */
const PROJ_PATCH = {
 "p-policy":{topic:"grc",lvl:2,hints:["Pick one structure and use it for all three policies.","Read each 'must' and ask: could an auditor test this with evidence?","The incident policy needs real clocks: CERT-In 6 hours and DPDP Board intimation."]},
 "p-dsar":{topic:"privops",lvl:1,hints:["Map every system — including vendors — where the person's data might be.","Erasure isn't absolute; list what law makes you keep.","Use a formula so deadlines calculate themselves."]},
 "p-ropa-dpia":{topic:"privops",lvl:3,hints:["Draw the data flow before filling the RoPA.","Biometrics of EU staff are special category data under GDPR Art. 9.","Ask: is there a less intrusive way to achieve the same goal?"]},
 "p-risk":{topic:"risk",lvl:2,hints:["Write your 1–5 scales before scoring anything.","Use 'Because of…, … could…, leading to…' for each risk.","Residual can never be higher than inherent."]},
 "p-vendor":{topic:"tprm",lvl:2,hints:["Tier from the data the vendor will hold.","Every 'yes' needs a link to public evidence; 'unknown' is a finding.","Check breach notice timing and sub-processor rules in the DPA."]},
 "p-dpdp-gap":{topic:"dpdp",lvl:3,hints:["Look for four traps in the scenario: contacts, marketing, retention and hosting.","'Not evidenced' counts as a gap.","Separate DPDP duties from RBI rules but show the overlap."]},
 "p-audit":{topic:"audit",lvl:2,hints:["Count business days, not calendar days.","Friday → Monday is one business day.","A wrong signer is an exception even if the date is fine."]},
 "p-ir":{topic:"c-ir",lvl:3,hints:["Start every clock at 09:10 Monday.","List each regulator separately: CERT-In, DPDP Board, RBI, US subsidiary.","The customer notice must say what people should do."]},
 "p-iso-soa":{topic:"iso",lvl:3,hints:["Choose controls from all four Annex A themes.","Every exclusion needs a reason an auditor would accept.","The roadmap must include internal audit and management review before Stage 1."]},
 "p-ai":{topic:"aigov",lvl:3,hints:["Decide provider vs deployer for each AI use first.","Hiring and credit scoring are Annex III high-risk.","Use the revised December 2027 date for high-risk duties."]},
 "p-dashboard":{topic:"t-excel",lvl:3,hints:["Choose metrics a board member would ask about.","Define green/amber/red thresholds before building charts.","Lead the briefing with status and decisions needed."]}
};
